question.intro:
נתונה מחלקה שחקן, Actor, שיש לה שלוש תכונות: מספר תעודת זהות id מטיפוס מחרוזת, מין השחקן gender מטיפוס מחרוזת ("F" מייצג נקבה, "M" מייצג זכר), ומספר הסרטים שהשחקן השתתף בהם numFilms מטיפוס שלם.
לפניך ממשק המחלקה Actor:
פעולה בונה, שבונה שחקן שמספר תעודת הזהות שלו id, מינו gender, ומספר הסרטים שהשתתף בהם numFilms:
public Actor(String id, String gender, int numFilms)
פעולה שמוסיפה 1 למספר הסרטים שהשחקן השתתף בהם:
public void addFilm()
פעולה שמחזירה 1 אם מספר הסרטים שהשחקן הנוכחי השתתף בהם גדול ממספר הסרטים שהשחקן other השתתף בהם, 2 אם הוא קטן ממנו, ו-3 אם הם שווים:
public int compare(Actor other)
הנח שלכל תכונה הוגדרו פעולות get ו-set.

classes.code:
public class Actor {
    private String id;
    private String gender;
    private int numFilms;

    public void addFilm() {
        numFilms++;
    }

    public String getId() { return id; }
    public void setId(String id) { this.id = id; }
    public String getGender() { return gender; }
    public void setGender(String gender) { this.gender = gender; }
    public int getNumFilms() { return numFilms; }
    public void setNumFilms(int numFilms) { this.numFilms = numFilms; }
}

tasks.solution:
public Actor(String id, String gender, int numFilms) {
    this.id = id;
    this.gender = gender;
    this.numFilms = numFilms;
}

public int compare(Actor other) {
    if (numFilms > other.getNumFilms()) {
        return 1;
    }
    if (numFilms < other.getNumFilms()) {
        return 2;
    }
    return 3;
}

public static void printMoreFilms(Actor[] actArr, int num) {
    int count = 0;
    for (int i = 0; i < actArr.length; i++) {
        if (actArr[i].getNumFilms() > num) {
            count++;
        }
    }
    System.out.println(count);
}

givenCode.code:
public static String check(Object got, Object expected) {
    String g = String.valueOf(got);
    String e = String.valueOf(expected);
    if (g.equals(e)) {
        return "נכון";
    }
    return "לא נכון — התקבל " + g + ", צריך להתקבל " + e;
}

exercise.mainCode:
Actor a = new Actor("123456789", "F", 5);
System.out.println("סעיף א, בדיקה 1: " + check(a.getId() + " " + a.getGender() + " " + a.getNumFilms(), "123456789 F 5"));
Actor b = new Actor("987654321", "M", 3);
System.out.println("סעיף א, בדיקה 2: " + check(b.getId() + " " + b.getGender() + " " + b.getNumFilms(), "987654321 M 3"));
System.out.println("סעיף ב, בדיקה 1: " + check(a.compare(b), 1));
System.out.println("סעיף ב, בדיקה 2: " + check(b.compare(a), 2));
b.addFilm();
b.addFilm();
System.out.println("סעיף ב, בדיקה 3: " + check(a.compare(b), 3));
Actor[] actArr = new Actor[37];
for (int i = 0; i < actArr.length; i++) {
    actArr[i] = new Actor("" + (100 + i), i % 2 == 0 ? "F" : "M", i % 10);
}
System.out.print("סעיף ג, בדיקה 1 (צריך להדפיס 13): ");
printMoreFilms(actArr, 5);
System.out.print("סעיף ג, בדיקה 2 (צריך להדפיס 3): ");
printMoreFilms(actArr, 8);
System.out.print("סעיף ג, בדיקה 3 (צריך להדפיס 0): ");
printMoreFilms(actArr, 9);

